using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Payments.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;namespace Namaa.Application.Payments.Commands.CreatePayment;public sealed class CreatePaymentCommandHandler(IPaymentRepository repository,IApplicationDbContext db):IRequestHandler<CreatePaymentCommand,Result<PaymentDto>>{public async Task<Result<PaymentDto>>Handle(CreatePaymentCommand request,CancellationToken cancellationToken){if(await repository.ExistsByPaymentNumberAsync(request.PaymentNumber,cancellationToken))return Result.Failure<PaymentDto>(PaymentErrors.Duplicate);var e=Payment.Create(request.PaymentNumber,request.PaymentDate,request.PaymentMethod,request.Amount,request.ReceivedByUserId,request.InvoiceId,request.CustomerId,request.ReferenceNumber,request.Notes);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(PaymentDto.FromEntity(e));}}
